"""Render a focused actual-reference comparison and seal reproducible evidence."""
from review_surface import *
import platform
import scipy,PIL

def run():
 m,a=load_measurement();ma=gzread(BASE/'generated/panel_master.json.gz');sf=np.load(BASE/'generated/continuous_surface.npz');r=gzread(BASE/'generated/common125.render.json.gz');v=sf['vertices'];center=(v.min(0)+v.max(0))/2;span=float(max(v.max(0)-v.min(0))*1.5)
 sheet=Image.new('RGB',(1536,1120),'white');d=ImageDraw.Draw(sheet);d.text((15,10),'APPROVED VIOLET r06 | original upper waist flap / measured continuous patch / actual common12.5mm ROI',fill='black')
 for i,name in enumerate(['front','side','back']):
  im=Image.fromarray(SOURCE).crop(A['views'][name]['crop_review']);im.thumbnail((480,320));im=im.resize((im.width*2,im.height*2));im.thumbnail((480,320));sheet.paste(im,(512*i+15,45));d.text((512*i+15,340),name+(' | counterpart UNKNOWN' if name=='back' else ' | candidate same flap, oblique camera' if name=='side' else ' | visible patch; root uncertain'),fill='black')
 src=source_render(v,sf['triangles'],ma['materials']);cams=[('front',0,0),('3/4',45,12),('side90',90,0),('back',180,0)]
 for row,(name,render) in enumerate([('Continuous minimum-curvature surface: depth/hidden closure are explicit priors',src),('Same source compiled at12.5mm:295 cells /1 six-connected component; reference matching NOT passed',r)]):
  yy=380+row*325;d.text((15,yy),name,fill='black')
  for i,(view,yaw,tilt) in enumerate(cams):
   im=raster(render,math.radians(yaw),math.radians(tilt),center,span,size=300);sheet.paste(im,(384*i+40,yy+20));d.text((384*i+45,yy+301),view,fill='black')
 lines=['Reference-fit limits: side visible coverage49.6%; back candidate support44.3%. Rolled underside / root identity unresolved.','Actual128 source pixels ->128 measured pixels -> this patch only ->7 cells changed. Same-input/master/common-mesh replay exact.','White review material is not the completed two-sided costume palette. Character/body/skin/face/hair not changed; GPU/rig/socket not validated.']
 for i,line in enumerate(lines):d.text((15,1045+i*22),line,fill='black')
 out=BASE/'generated/approved_roi_actual_panel_comparison.jpg';sheet.save(out,quality=91)
 write(BASE/'evidence/focused_comparison_provenance.json',{'approved_reference_sha256':A['source_sha256'],'reference_crops':{k:v['crop_review'] for k,v in A['views'].items()},'master_sha256':sha(BASE/'generated/panel_master.json.gz'),'continuous_surface_sha256':sha(BASE/'generated/continuous_surface.npz'),'common_render_sha256':sha(BASE/'generated/common125.render.json.gz'),'renderer_sha256':sha(CPU_SOURCE),'comparison_script_sha256':sha(__file__),'comparison_sha256':sha(out),'fixed_camera':{'center_m':center.tolist(),'span_m':span,'views':cams},'native_pixels_and_actual_CPU_triangles':True,'generated_beauty_or_retouch':False})
 write(BASE/'evidence/runtime_environment.json',{'python':platform.python_version(),'numpy':np.__version__,'scipy':scipy.__version__,'Pillow':PIL.__version__,'OPENBLAS_NUM_THREADS':os.environ.get('OPENBLAS_NUM_THREADS'),'OMP_NUM_THREADS':os.environ.get('OMP_NUM_THREADS')})
 # Verify older frozen closure snapshots remain unmodified.
 checks={}
 for old in [ROOT/'continuous04/closure.json',ROOT/'full01/closure.json']:
  dd=read(old);changed=[f['path'] for f in dd['files'] if not (REPO/f['path']).is_file() or sha(REPO/f['path'])!=f['sha256']];checks[str(old.relative_to(REPO))]={'closure_sha256':sha(old),'checked_files':len(dd['files']),'changed':changed}
 write(BASE/'evidence/previous_frozen_closure_integrity.json',checks);assert all(not v['changed'] for v in checks.values())
 # Entire predecessor output sets are included as failures; no later research.
 files=set()
 for directory in [ROOT/'continuous05',ROOT/'continuous05b',BASE]:
  files.update(p for p in directory.rglob('*') if p.is_file() and '__pycache__' not in str(p) and p.name!='closure.json')
 files.update([REPO/A['source'],REPO/C['original'],REPO/A['alignment_contract'],ROOT/'full01/generated/volume_master_v03.json.gz',ROOT/'tools/measured_panels.py',ROOT/'tools/verify_and_render.py',ROOT.parent/'r08/tools/render_evaluate.py',ROOT.parent/'r08/tools/measured_cloth.py',COMMON/'core.py',COMMON/'render_data.py',REPO/'voxel_character/tools/mesh.py'])
 records=[{'path':str(p.relative_to(REPO)),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(files)]
 closure={'schema':'riverstone.r10.continuous05c.frozen_closure.v1','status':'BOUNDED_MEASURED_PANEL_PROCESS_AND_ROI_CONNECTIVITY_CHECKED__REFERENCE_FIT_AND_COMPLETE_CHARACTER_UNAPPROVED','approved_reference':{'path':A['source'],'sha256':A['source_sha256'],**C['approval'],'approval_is_image_not_geometry':True},'chain':'approved source pixels -> explicit semantic/correspondence/uncertainty annotations -> independently saved edge/mask measurements -> bounded minimum-curvature visible surface -> normal-thickness common primitives -> common compiler -> CPU geometry/projection checks','scope':'one provisional upper waist-flap visible patch only; no cyan/Lily/full-body replacement','preserved_failures':['continuous05 upper-edge omission and blanket root-occlusion mistake','continuous05b false low-confidence edge displacement/self-crossing and25/12.5mm disconnected outputs','continuous05c25mm3components; side/back mismatch, root/rolled-return ambiguity, incomplete costume palette'],'positive_checks':['input dependence and unrelated-region independence','same-input/saved-input/master/common-mesh replay','invalid/stale/missing/contradictory input rejection','05c1 source component, no contour crossing','same master/origin/thickness12.5mm ROI295cells1component','actual convex source-prism/torso intersections, not sewing ground truth'],'prohibited_interpretations':['not a completed3D character reconstruction','front projection1.0 follows from construction and is not independent art validation','12.5mm1component does not resolve side/back/hidden surfaces','positive torso overlap is not measured attachment anatomy'],'representative_outputs':[str(out.relative_to(REPO)),str((BASE/'generated/fixed_master_grid_comparison.jpg').relative_to(REPO)),str((BASE/'generated/source_overlay.jpg').relative_to(REPO))],'reproduce_in_separate_copy':'OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 python continuous05c/tools/measured_surface.py; review_surface.py; verify_surface.py; diagnose_grid.py; audit_measurement_contract.py; audit_root_contact.py; measure_view_sampling.py. Repo-relative paths must be retained. Do not overwrite sealed outputs in-place.','files':records,'file_count':len(records),'total_bytes':sum(f['bytes'] for f in records),'excluded':'next larger-region/body contracts or future iterations; bytecode caches','GPU_rig_socket_validated':False}
 write(BASE/'closure.json',closure);used=sum(p.stat().st_size for p in ROOT.rglob('*') if p.is_file());assert used<40*1048576;print(json.dumps({'closure_path':str((BASE/'closure.json').relative_to(REPO)),'closure_sha256':sha(BASE/'closure.json'),'file_count':len(records),'total_bytes':closure['total_bytes'],'r10_total_bytes':used,'comparison_sha256':sha(out)}))
if __name__=='__main__':run()
